    // Stick
    @State private var stickLength: Double = 0.0
    @State private var stickAngle: Double = 0.0 // 0 = vertical up, 90 = horizontal right

    // Stickman Position
    @State private var stickmanX: Double = 0.0
    @State private var stickmanY: Double = 0.0
