                                .foregroundColor(.black)
                            Text("最高分: \(highScore)")
                                .font(.system(size: 14, weight: .semibold))
                                .foregroundColor(.gray)
                        }
                        .padding(.leading, 20)

                        Spacer()

                        // Right Controls Panel
                        VStack(alignment: .trailing, spacing: 10) {
                            HStack(spacing: 12) {
                                Button(action: {
                                    withAnimation {
                                        showSettings.toggle()
                                    }
                                }) {
                                    Image(systemName: "slider.horizontal.3")
                                        .font(.system(size: 18, weight: .bold))
                                        .foregroundColor(.white)
                                        .padding(10)
                                        .background(Color.black)
                                        .clipShape(Circle())
                                }

                                Button(action: resetGame) {
                                    HStack(spacing: 4) {
                                        Image(systemName: "arrow.clockwise")
                                        Text("重置遊戲")
                                    }
                                    .font(.system(size: 14, weight: .bold))
                                    .foregroundColor(.white)
                                    .padding(.horizontal, 14)
                                    .padding(.vertical, 8)
                                    .background(Color.black)
                                    .cornerRadius(20)
                                }
                            }

                            // Expandable Settings Panel
                            if showSettings {
                                VStack(alignment: .leading, spacing: 12) {
                                    Text("遊戲參數設置")
                                        .font(.system(size: 15, weight: .bold))
                                        .foregroundColor(.black)

                                    Divider()

                                    // 1. Length / Platform Width Control (長度)
                                    VStack(alignment: .leading, spacing: 4) {
                                        HStack {
                                            Text("起始地面長度:")
                                                .font(.system(size: 13, weight: .medium))
                                            Spacer()
                                            Text("\(Int(initialPlatformWidth))")
                                                .font(.system(size: 13, weight: .bold))
                                        }
                                        Slider(value: $initialPlatformWidth, in: 50...250, step: 10) { _ in
                                            if gameState == .ready || gameState == .gameOver {
                                                currentPlatformWidth = initialPlatformWidth
                                                stickmanX = currentPlatformX + currentPlatformWidth - 14
                                            }
                                        }
                                    }

                                    // 2. Volatility Control (動盪區間 0~1)
                                    VStack(alignment: .leading, spacing: 4) {
